import{_ as e,c as p,o as r,ah as i}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"44、【姤】 巽下乾上","description":"周易尚氏學 - 44、【姤】 巽下乾上","frontmatter":{"title":"44、【姤】 巽下乾上","description":"周易尚氏學 - 44、【姤】 巽下乾上"},"headers":[],"relativePath":"classics/shangshi/049.md","filePath":"classics/shangshi/049.md"}'),s={name:"classics/shangshi/049.md"};function t(h,a,l,n,c,d){return r(),p("div",null,[...a[0]||(a[0]=[i('<h1 id="_44、【姤】-巽下乾上" tabindex="-1">44、【姤】 巽下乾上 <a class="header-anchor" href="#_44、【姤】-巽下乾上" aria-label="Permalink to “44、【姤】 巽下乾上”">​</a></h1><p>歸藏曰夜。古娶必以夜。故曰昏。後陰遇陽。即女遇男。亦婚姤也。是夜與姤義同也。女謂陰。虞翻雲。壯傷也。陰傷陽。柔消剛。故曰女壯。勿用取女。戒詞也。</p><p>彖。姤。遇也。柔遇剛也。勿用取女。不可與長也。天地相遇。品物鹹章也。剛遇中正。天下大行也。姤之時義大矣哉。</p><p>消息卦乾盈於巳。盈則必虧。故至午而一陰生於下。陰遇陽。故曰天地相遇。時當五月。萬物潔齊。而巽為草木。為高。為長。故曰品物鹹章。荀爽以南方夏位說品物鹹章。於象亦切也。五剛既中且正。教化天下。命令大行。如風之博遍。姤五月卦。故曰時。天地相遇。歲功方成。故曰時義大也。鄭玄謂姤一女當五男。非禮之正。故謂之振。女壯以淫。故不可取。而朱子喜用其說。便謂女德不貞。於易理太不類也。</p><p>象曰。天下有風。姤。後以施樹四方。</p><p>復冬至。姤夏至。易林復之履雲。先王日至。不利出城。又晉之解雲。二至之戒。家無兇禍。故復象雲。先王以至日閉關。商旅不行。後不省方。至日。王弼孔穎達皆謂二至。又漢書薛宣傳。至日休吏。由來已久。注。至日夏至冬至也。蓋古時視二至最重。自周訖南宋。可考見者。至日皆停止工作。乾為後。巽為命。伏坤為四方。後以施命浩四方者。言君以夏至之日。施命令止四方行旅也。後漢魯恭傳。說此。最合古義。詳焦氏易詁中。</p><p>初六。繫於金柅。貞吉。有攸往。見兇。贏豕孚蹢躅。</p><p>巽為繩。故曰系。巽木乾金。故曰金柅。馬融雲。柅在車下。所以止輪。釋文廣雅雲。止也。說文作稱（左木）。雲絡絲趺。按今本說文。跌訛為稱（左木）。雲人木稱（左木）聲。讀若柅。陶廬雲。古從爾從柅之字。同音通用。毛詩飲餞於爾（左 ）。韓詩作坭。書典祀勿。豐於呢。釋文引馬雲考也。謂稱廟也。然則柅稱（左木）古通用。後儒必謂爾（左木）是者非也。況馬君訓作止車木。可證古文原作柅。若為爾（左木）。馬君能有異說哉。按絡絲者。絡絲之器。王肅所謂柅織績之器。婦人用者是也。趺者橫木。安絡器下。以防欹側。在下似足。故謂之跌。唐陰宏道雲。絡器。關西謂之絡垛。梁益謂之絲登。其下附（左木）即柅也。按陰氏所謂附（左木）。即說文之趺。故玉篇即作絡絲附（左木）。陳壽棋雲。附（左木）趺同字。絡縛也。與系同義。繫於金尼者。言以絲縛於金柅之上。止而勿動。以喻陰不宜動而消陽。故下雲往見兇。是其義也。貞吉者。卜問吉。往見兇者。進則兇也。巽為贏（下中羊）為豕。巽進退。故蹢躅。羸釋文陸讀為累。鄭力追反。是仍讀為累。與大壯同。累纏繞也。羸累累音同通用。巽為繩故為贏。巽伏故亦為豕。蹢躅動也。羸豕孚蹢躅者。言豕雖拘贏。然蹢躅前進。信其必然。不可忽也。喻陰雖微。後必長也。巽豕象失傳。詳焦氏易詁易象補遺。</p><h3 id="象曰。繫於金柅。柔道牽也。" tabindex="-1">象曰。繫於金柅。柔道牽也。 <a class="header-anchor" href="#象曰。繫於金柅。柔道牽也。" aria-label="Permalink to “象曰。繫於金柅。柔道牽也。”">​</a></h3><p>玉篇。牽速也。下九三。象釋其行次且。曰行未牽也。是象傳亦訓牽為速。柔道牽者。言柔之為道。消陽甚速。故以金柅止之。諸家皆謂柔牽於二。失經旨。經旨恐陰進危陽。故止其動。象釋為柔道牽。申繫於金柅之故也。牽速之象取風疾。兼取巽繩。</p><p>九二。苞有魚。無咎。不利實。</p><p>苞今本作包。書禹貢草木漸包。釋文或作苞。是包苞古通。故虞氏作苞。見釋文。虞雲巽為白茅。詩白茅苞之。巽為魚。二據陰居中。故曰苞有魚。巽為賓客。不利賓者。賓指上四陽。言初為二所據。四陽不能及初也。子夏傳作庖。而荀爽則作胞。胞 通。是皆以庖廚為義。然卦元是象。故虞氏合也。</p><h3 id="象曰。苞有魚。義不及賓也。" tabindex="-1">象曰。苞有魚。義不及賓也。 <a class="header-anchor" href="#象曰。苞有魚。義不及賓也。" aria-label="Permalink to “象曰。苞有魚。義不及賓也。”">​</a></h3><p>二近。賓遠。故義不及。</p><p>九三。臀無膚。其行次且。厲。無大咎。</p><p>三居下卦之末。故亦曰臀。初陰爻。下爛。故曰無膚。乾為行。三得敵。故次且不前。然三當位。故雖危厲而無大咎也。舊解皆不知次且之故何在。而以復震為行為說。失之遠矣。</p><h3 id="象曰。其行次且。行未牽也。" tabindex="-1">象曰。其行次且。行未牽也。 <a class="header-anchor" href="#象曰。其行次且。行未牽也。" aria-label="Permalink to “象曰。其行次且。行未牽也。”">​</a></h3><p>行未牽。即行未速。次且者卻行未前。故日未速。</p><p>九四。 苞無魚。起兇。</p><p>四應初。疑於有魚。豈知初已為二所據。實無魚也。無魚則勿動。動應初則為二三所害。故兇。起作也。</p><h3 id="象曰。無魚之兇。遠民也。陰為民。言四距初遠。故無魚也。" tabindex="-1">象曰。無魚之兇。遠民也。陰為民。言四距初遠。故無魚也。 <a class="header-anchor" href="#象曰。無魚之兇。遠民也。陰為民。言四距初遠。故無魚也。" aria-label="Permalink to “象曰。無魚之兇。遠民也。陰為民。言四距初遠。故無魚也。”">​</a></h3><p>九五。以把苞瓜。含章。有隕自天。</p><p>下巽為杞。上乾為圜。為瓜。孟子告於曰。以人性為仁義。猶以杞柳為否（左木）卷（左木）。說文否（左木）？也。卷（左木）屈木盂也。以杞苞瓜者。言以杞柳之器盛瓜也。乾為大明。故曰章。瓜為所苞。故曰含章。五承乘皆陽。行窒。故含章自守。五天位。巽為隕。有隕自天者。言不久明消至二。五與為應。有隕落之險也。知其險而預為之備。則得矣。此聖人防微慮遠之意也。自荀虞以來。皆不知左傳有風隕象。因之清儒亦皆不知。於是虞氏令四隕初之說。沿襲至今。而經義全晦。復六五曰敦復無侮。待陽息至二。五有應而古。此則廬陽消至二。五應之而兇。</p><h3 id="象曰。九五含章。中正也。有隕自天。志不捨命也。" tabindex="-1">象曰。九五含章。中正也。有隕自天。志不捨命也。 <a class="header-anchor" href="#象曰。九五含章。中正也。有隕自天。志不捨命也。" aria-label="Permalink to “象曰。九五含章。中正也。有隕自天。志不捨命也。”">​</a></h3><p>巽為命。捨命謂任命也。志不捨命者。言知其後有隕落之險。不任命而預防之也。</p><p>上九。柅其角。吝。無咎。</p><p>乾為首。上九居乾之上。角之象也。故曰姤其角。然亦無大咎也。</p><h3 id="象曰。柅其角。上窮吝也。" tabindex="-1">象曰。柅其角。上窮吝也。 <a class="header-anchor" href="#象曰。柅其角。上窮吝也。" aria-label="Permalink to “象曰。柅其角。上窮吝也。”">​</a></h3><p>處亢龍之位。故窮吝。</p>',29)])])}const m=e(s,[["render",t]]);export{_ as __pageData,m as default};
